--changeset gaurav:005-countries-table

CREATE TABLE COUNTRIES (
    COUNTRY_CODE INTEGER PRIMARY KEY,
    COUNTRY_NAME_ENGLISH VARCHAR(128),
    COUNTRY_NAME_ARABIC VARCHAR(128),
    ISO3_CODE VARCHAR(26),
    ISO2_CODE VARCHAR(26),
    COUNTRY_DIAL_CODE VARCHAR(26),
    FIT_COUNTRY_CODE INTEGER,
    FIT_NATIONALITY_CODE INTEGER,
    ADX_CODE VARCHAR(26),
    ACTIVE INTEGER,
    SORT INTEGER,
    CURRENCY_CODE VARCHAR(3)
);

